<script setup>
import {ref,onMounted} from 'vue'
import {folderApi} from '../api/enhancements.js'
defineProps({selected:String});const emit=defineEmits(['select','loaded','changed'])
const folders=ref([]),name=ref(''),busy=ref(false),error=ref(''),confirming=ref(false)
async function load(){folders.value=await folderApi.list();emit('loaded',folders.value)}
async function run(action){if(busy.value)return;busy.value=true;error.value='';try{await action();name.value='';confirming.value=false;await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="folder-panel"><div class="folder-links"><strong>私人收藏夹</strong><button class="secondary" :class="{active:!selected}" @click="emit('select','')">全部收藏</button><button class="secondary" :class="{active:selected==='0'}" @click="emit('select','0')">未分组</button><button v-for="f in folders" :key="f.id" class="secondary" :class="{active:selected===String(f.id)}" @click="emit('select',String(f.id))">{{f.name}}</button></div><form class="folder-actions" @submit.prevent="run(()=>folderApi.create(name))"><input v-model="name" aria-label="收藏夹名称" maxlength="80" placeholder="输入新建或重命名后的名称" required/><button class="secondary" :disabled="busy">新建收藏夹</button><button v-if="selected&&selected!=='0'" class="secondary" type="button" :disabled="busy||!name.trim()" @click="run(()=>folderApi.rename(selected,name))">重命名当前收藏夹</button><button v-if="selected&&selected!=='0'" class="text-button" type="button" :disabled="busy" @click="confirming=!confirming">移除当前收藏夹</button></form><div v-if="confirming" class="message"><p>只移除收藏夹，收藏资源归回“未分组”，不会删除资源或取消收藏。</p><button class="secondary" :disabled="busy" @click="run(async()=>{await folderApi.remove(selected);emit('select','0')})">确认移除收藏夹</button><button class="text-button" @click="confirming=false">取消</button></div><p v-if="error" class="message error" role="alert">{{error}}</p></section></template>
<style scoped>.folder-panel{margin-bottom:22px;padding-bottom:18px;border-bottom:1px solid var(--line)}.folder-links,.folder-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px}.folder-links strong{font-size:13px;margin-right:8px}.folder-links .active{background:var(--primary);color:white;border-color:var(--primary)}.folder-actions{margin-top:14px}.folder-actions input{max-width:300px;font-size:12px}</style>
